<?php
namespace App\Http\Controllers;
use App\Models\User; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Support\Facades\Artisan;
class InstallController extends Controller { public function index(){if(file_exists(storage_path('app/installed.lock')))return redirect('/login');try{DB::connection()->getPdo();$db=true;}catch(\Throwable){$db=false;}return view('install',compact('db'));} public function store(Request $r){abort_if(file_exists(storage_path('app/installed.lock')),404);$d=$r->validate(['name'=>'required|max:120','username'=>'required|alpha_dash|unique:users','email'=>'required|email|unique:users','password'=>'required|confirmed|min:12']);try{DB::connection()->getPdo();Artisan::call('migrate',['--force'=>true]);User::create($d+['role'=>'admin']);file_put_contents(storage_path('app/installed.lock'),now()->toIso8601String());return redirect('/login')->with('status','Installation complete.');}catch(\Throwable $e){return back()->withErrors(['install'=>'Installation failed. Check database configuration and logs.']);}} }
